+#!/usr/bin/env python3
+"""ag45_field.py — androguard field-xref decode for a target APK.
+
+Given an APK + class + field names, decode WHO writes and WHO reads each
+field (method-level xref via androguard Analysis). Kills wrong hypotheses in
+one pass (e.g. #560: int-field store loss REFUTED by FIELD-TRACE round-trip).
+
+Usage: ag45_field.py <apk> <class-dotted-or-L-form> [field1 field2 ...]
+Default target (no args): headingcalculator CalculatorDisplay display fields.
+"""
+import sys, json, zipfile, io, os
+from loguru import logger
+logger.remove()
+from androguard.core.dex import DEX
+
+DEFAULT_APK = "/home/z/my-project/upload/canonical_apks_restored/org.debian.eugen.headingcalculator_1.apk"
+DEFAULT_CLASS = "Lorg/debian/eugen/headingcalculator/CalculatorDisplay;"
+DEFAULT_FIELDS = ["mTrueCourse", "mTrueAirspeed", "mWindDirection", "mWindSpeed"]
+
+def dexes_of(apk_path):
+    z = zipfile.ZipFile(apk_path)
+    return [DEX(z.read(n))
+            for n in sorted(x for x in z.namelist()
+                            if x.startswith("classes") and x.endswith(".dex"))]
+
+def main():
+    apk = sys.argv[1] if len(sys.argv) > 1 else DEFAULT_APK
+    cls = sys.argv[2] if len(sys.argv) > 2 else DEFAULT_CLASS
+    if not cls.startswith("L"):
+        cls = "L" + cls.replace(".", "/") + ";"
+    fields = sys.argv[3:] if len(sys.argv) > 3 else DEFAULT_FIELDS
+
+    dexes = dexes_of(apk)
+    target_field_keys = {f"{cls}-> {f}" for f in fields}
+
+    writers = {f: set() for f in fields}
+    readers = {f: set() for f in fields}
+    decl = {}
+    for d in dexes:
+        for c in d.get_classes():
+            if c.get_name() != cls:
+                continue
+            for f in c.get_fields():
+                if f.get_name() in fields:
+                    decl[f.get_name()] = f.get_descriptor()
+            for m in c.get_methods():
+                try:
+                    if m.get_code() is None:
+                        continue
+                    insts = m.get_instructions()
+                except Exception:
+                    continue
+                for inst in insts:
+                    op = inst.get_name()
+                    if not (op.startswith("iput") or op.startswith("iget")
+                            or op.startswith("sput") or op.startswith("sget")):
+                        continue
+                    try:
+                        operands = inst.get_operands()
+                        if not operands:
+                            continue
+                        ref = operands[-1][2] if len(operands[-1]) > 2 else ""
+                        # androguard 4.1.4 renders field refs as
+                        #   Lcls;->fieldName descriptor   (SPACE, no colon)
+                        # older versions used  Lcls;->fieldName:descriptor
+                        if "->" not in ref:
+                            continue
+                        fcls, rest = ref.split("->", 1)
+                        fname = rest.replace(":", " ").split(" ")[0]
+                        if fcls == cls and fname in fields:
+                            sig = f"{c.get_name()}->{m.get_name()}{m.get_descriptor()}"
+                            if op.startswith(("iput", "sput")):
+                                writers[fname].add(sig)
+                            else:
+                                readers[fname].add(sig)
+                    except Exception:
+                        pass
+
+    out = {
+        "apk": os.path.basename(apk),
+        "class": cls,
+        "fields": {
+            f: {
+                "descriptor": decl.get(f, "?"),
+                "writers": sorted(writers[f]),
+                "readers": sorted(readers[f]),
+            } for f in fields
+        },
+    }
+    print(json.dumps(out, indent=1))
+    # non-zero exit only if NOTHING was found (target class absent)
+    if not decl:
+        sys.exit(2)
+
+if __name__ == "__main__":
+    main()
